    # We want to find max |sum| for each a, and then find the minimum of those maxes.
    best_c = float('inf')

    import itertools
    for a in itertools.product([1, -1], repeat=n):
        # dp[i] is the set of possible sums ending at index i
        dp = [set() for _ in range(n)]
        max_abs_sum = 0
        for i in range(n):
            dp[i].add(a[i])
            if i >= 1:
                for s in dp[i-1]:
                    dp[i].add(s + a[i])
            if i >= 2:
                for s in dp[i-2]:
                    dp[i].add(s + a[i])

            for s in dp[i]:
                max_abs_sum = max(max_abs_sum, abs(s))

        best_c = min(best_c, max_abs_sum)
