def solve_small(n):
    import itertools
    min_max_sum = float('inf')
    # Only need to check n up to some small value
    for a in itertools.product([1, -1], repeat=n):
        current_max_sum = 0
        # We need to find the maximum sum over all valid subsequences
        # A subsequence is valid if the distance between consecutive indices is <= 2.
        # Let dp[i] be the set of all possible sums of valid subsequences ending at index i.
        # Or better, dp[i] = max sum ending at i. But we want the max absolute sum.
        # So we need to keep track of the range of sums? No, just the max and min.
        # Let f[i] = set of possible sums ending at index i.
        f = [set() for _ in range(n)]
        for i in range(n):
            f[i].add(a[i])
            if i >= 1:
                for s in f[i-1]:
                    f[i].add(s + a[i])
            if i >= 2:
                for s in f[i-2]:
                    f[i].add(s + a[i])

        all_sums = set()
        for i in range(n):
            all_sums.update(f[i])

        current_max_abs_sum = max(abs(s) for s in all_sums)
        if current_max_abs_sum < min_max_sum:
            min_max_sum = current_max_abs_sum

    return min_max_sum

