def check_formula_correct(n, C):
    # We want to know if there exists a sequence a such that 
    # for all i, S[i] \subseteq \{-(C-1), \dots, C-1\}
    # where S[i] = {a[i]} \cup {s + a[i] | s \in S[i-1] \cup S[i-2]}
    # If such a sequence exists, then the minimum maximum sum is < C.
    # So the largest C such that for any sequence there exists a sum >= C
    # is the smallest C such that NO such sequence exists.

    # This means C = min_a (max |sum|).
    # So for a given n, we want to find the smallest C such that 
    # check_formula(n, C) is False.

    memo = {}
    def dfs(i, S_prev1, S_prev2):
        state = (i, tuple(sorted(list(S_prev1))), tuple(sorted(list(S_prev2))))
        if state in memo:
            return memo[state]
        if i == n:
            return True
        for val in [1, -1]:
            new_S = {val}
            possible = True
            # All sums must be < C
            # But wait, a sequence is a counterexample if there is ANY sum >= C.
            # So we want a sequence where NO sum is >= C.
